"""11-17: Canada, first pack. Books chosen with the scoring rubric (sel/ca: CBC 100 lists + Marburg minimal canon, GG / Giller /
Booker and other prizes, Goodreads, BBC "Novels That Shaped Our World"): the 35 the rubric picked plus the five nearest misses the
user asked for (Late Nights on Air, Mrs. Mike, Through Black Spruce, The Diviners, I Heard the Owl Call My Name; A Season in the
Life of Emmanuel and Bear were skipped for having no real place). Gutenberg is down, so every book gets scene notes for now.
Coordinates come from Commons categories or geotagged Commons photos (coords_ca.json, made by the coordinate step).
Usage: python3 -I add_ca1.py <app_dir> <coords_ca.json>"""
import json, os, sys
sys.path.insert(0, __file__.rsplit("/", 2)[0])
import batchlib as b
APP, CO = sys.argv[1], json.load(open(sys.argv[2], encoding="utf-8"))
b.init(APP, "", "ca", "2026-11-17")
W, G = b.W, b.G

def BK(id, title, title_zh, author, author_zh, year, pg=None, pd=False, **kw):
    d = dict(id=id, title=title, title_zh=title_zh, author=author, author_zh=author_zh, year=year, orig_lang=kw.pop("lang", "en"),
             public_domain=pd, source_url=(G + str(pg)) if pg else None)
    d.update(kw)
    return d

def C(pid):
    c = CO[pid]
    return c["lat"], c["lon"], c["st"], c["su"]

def ORIG(pid, name, zh, en_note, zh_note, **kw): return b.ORIG(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PROTO(pid, name, zh, en_note, zh_note, **kw): return b.PROTO(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PIL(pid, name, zh, en_note, zh_note, ids, **kw): return b.PIL(pid, name, zh, *C(pid), en_note, zh_note, ids, **kw)
S = b.S

